}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
public void postLoad()
{
    next postLoad();

    CustConfirmJour         custConfirmJour;

    select firstonly custConfirmJour
         where custConfirmJour.ConfirmId   == this.ConfirmationNumber
            && CustConfirmJour.ConfirmDate == this.ConfirmationDate
            && CustConfirmJour.SalesId     == this.SalesOrderNumber;

    EcoResProductTranslation avaProductTranslation = EcoResProductTranslation::findByProductLanguage(InventTable::itemProduct(this.ItemId),  CustConfirmJour.LanguageId);
    this.AVAItemName1 = avaProductTranslation.NDXProductName1;
    this.AVAItemName2 = avaProductTranslation.NDXProductName2;
}
